SELECT c.ID,c.name ,c.SEAT_COUNT,
(select SUM(t.END_POSITION)-SUM(t.START_POSITION)+COUNT(*) from ASSET_ATTACH t where t.CABINET_ID=#{cabinetId})
as USED_SEAT,
(select COUNT(*) from ASSET_ATTACH v where v.CABINET_ID=#{cabinetId}) as ASSET_SIZE ,
(concat(concat(concat(c.ROW_INDEX,'行'),c.COLUMN_INDEX),'列')) as POSITION,
a.ASSET_ID,b.name as asset_name,b.ASSET_MODE ,a.START_POSITION,a.END_POSITION,
(
select count(*) from ALARM_INFO d where d.ASSET_ID = a.ASSET_ID


        and d.STATUS = #{status}


        and d.ALARM_STATE = #{alarmState}





            and (d.STATUS = #{status} or d.ALARM_STATE = #{alarmState})


            and d.STATUS = #{status}


            and d.ALARM_STATE = #{alarmState}




    and d.blank = #{blank}


    and (b.ASSET_SUPPLIER != 'JCCA' or b.ASSET_SUPPLIER is null)

) as alarm_size,
(
select min(e.ALARM_LEVEL) from ALARM_INFO e where e.ASSET_ID = a.ASSET_ID


        and e.STATUS = #{status}


        and e.ALARM_STATE = #{alarmState}





            and (e.STATUS = #{status} or e.ALARM_STATE = #{alarmState})


            and e.STATUS = #{status}


            and e.ALARM_STATE = #{alarmState}




    and e.blank = #{blank}


    and (b.ASSET_SUPPLIER != 'JCCA' or b.ASSET_SUPPLIER is null)

) as alarm_level
from CABINET c
left join ASSET_ATTACH a on a.CABINET_ID = c.id
left join asset b on a.ASSET_ID = b.id
where c.id = #{cabinetId}


    and (b.ID IN






                        ) OR a.ASSET_ID IN (

                    ,


            #{Id}


    )

select DISTINCT (CABINET_ID)
from ASSET_ATTACH c
         join (
    select ID
    from asset
    where name like CONCAT(CONCAT('%', #{keyword}), '%')
       or ip = #{keyword}
) a on c.ASSET_ID = a.id
where ROOM_ID = #{roomId}
